import js from "@eslint/js"
import importPlugin from "eslint-plugin-import"
import unicorn from "eslint-plugin-unicorn"
import tseslint from "typescript-eslint"
import {
  ambientAuthority,
  hostPath,
  invariants,
  swallowedCause,
  uninstalledSafety
} from "../../../../eslint.invariants.js"
import { jsdocConvention } from "../../../../eslint.jsdoc.js"

export default tseslint.config(
  {
    ignores: ["**/dist", "**/build", "**/coverage"]
  },
  js.configs.recommended,
  importPlugin.flatConfigs.recommended,
  importPlugin.flatConfigs.typescript,
  {
    files: ["src/**/*.ts"],
    extends: [tseslint.configs.recommended],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname
      }
    },
    settings: {
      "import/resolver": {
        typescript: {
          project: ["./tsconfig.json"]
        }
      }
    },
    plugins: {
      unicorn
    },
    rules: {
      "@typescript-eslint/array-type": ["error", { default: "generic", readonly: "generic" }],
      "@typescript-eslint/consistent-type-imports": ["error", { fixStyle: "inline-type-imports" }],
      "@typescript-eslint/no-explicit-any": "off",
      "@typescript-eslint/no-import-type-side-effects": "error",
      "@typescript-eslint/no-unnecessary-type-assertion": "error",
      "@typescript-eslint/no-unnecessary-type-constraint": "error",
      "@typescript-eslint/no-unused-vars": ["error", { argsIgnorePattern: "^_", varsIgnorePattern: "^_" }],
      "@typescript-eslint/no-useless-empty-export": "error",
      "import/no-duplicates": "error",
      "import/no-empty-named-blocks": "error",
      "import/no-self-import": "error",
      "no-await-in-loop": "off",
      "no-console": "error",
      "no-fallthrough": "off",
      "no-shadow": "off",
      "no-unneeded-ternary": "error",
      "no-unused-vars": "off",
      "no-useless-concat": "error",
      "no-useless-constructor": "error",
      "no-var": "error",
      "object-shorthand": "off",
      "require-yield": "off",
      "unicorn/no-abusive-eslint-disable": "error",
      "unicorn/no-accessor-recursion": "error",
      "unicorn/prefer-array-flat-map": "error"
    }
  },
  ...jsdocConvention,
  ...invariants(uninstalledSafety, swallowedCause, ambientAuthority, hostPath)
)

{
  "name": "@smthrs/artifacts",
  "type": "module",
  "version": "1.0.0-rc.16",
  "license": "MIT",
  "smthrs": {
    "group": "engine"
  },
  "description": "Effect service for the Smithers content-addressed artifact store, local and remote",
  "homepage": "https://github.com/smithersai/smithers",
  "repository": {
    "type": "git",
    "url": "https://github.com/smithersai/smithers.git",
    "directory": "packages/smithers/flows/artifacts"
  },
  "bugs": {
    "url": "https://github.com/smithersai/smithers/issues"
  },
  "tags": [
    "typescript",
    "effect",
    "cache",
    "content-addressed"
  ],
  "keywords": [
    "typescript",
    "effect",
    "cache",
    "content-addressed"
  ],
  "engines": {
    "node": ">=22.19.0"
  },
  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./internal/*": null,
    "./*/index": null,
    "./ArtifactBackupLease": "./src/ArtifactBackupLease.ts",
    "./ArtifactStore": "./src/ArtifactStore.ts",
    "./ArtifactStoreMetrics": "./src/ArtifactStoreMetrics.ts",
    "./ArtifactSweep": "./src/ArtifactSweep.ts",
    "./CombinedArtifacts": "./src/CombinedArtifacts.ts",
    "./FileLease": "./src/FileLease.ts",
    "./RemoteArtifacts": "./src/RemoteArtifacts.ts",
    "./index": "./src/index.ts"
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*.js",
    "dist/**/*.js.map",
    "dist/**/*.d.ts",
    "dist/**/*.d.ts.map",
    "dist/**/package.json",
    "LICENSE",
    "README.md",
    "CHANGELOG.md",
    "docs/"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true,
    "tag": "next",
    "exports": {
      "./package.json": "./package.json",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./internal/*": null,
      "./*/index": null,
      "./ArtifactBackupLease": {
        "import": {
          "types": "./dist/esm/ArtifactBackupLease.d.ts",
          "default": "./dist/esm/ArtifactBackupLease.js"
        },
        "require": {
          "types": "./dist/cjs/ArtifactBackupLease.d.ts",
          "default": "./dist/cjs/ArtifactBackupLease.js"
        }
      },
      "./ArtifactStore": {
        "import": {
          "types": "./dist/esm/ArtifactStore.d.ts",
          "default": "./dist/esm/ArtifactStore.js"
        },
        "require": {
          "types": "./dist/cjs/ArtifactStore.d.ts",
          "default": "./dist/cjs/ArtifactStore.js"
        }
